CREATE OR REPLACE FUNCTION public.fn_folha_destino_operar_v3(p_dados jsonb,p_confirmar boolean DEFAULT false,p_versao text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $destinationrefs$
DECLARE u public.utilizadores;p uuid:=(p_dados->>'person_id')::uuid;w uuid:=(p_dados->>'work_id')::uuid;d date:=(p_dados->>'date')::date;k text:=p_dados->>'kind';req uuid:=(p_dados->>'request_id')::uuid;child jsonb;preview jsonb;xs jsonb;refs jsonb;payload jsonb;token text;outcome jsonb;op folha_privado.operacoes;cnt integer;
BEGIN
 LOCK TABLE public.quadro_pessoal_alocacao IN ROW EXCLUSIVE MODE;PERFORM pg_advisory_xact_lock(61001,1);u:=folha_privado.ator();child:=p_dados||jsonb_build_object('request_id',md5(req::text||':destination_refs')::uuid);preview:=folha_privado.destino_sem_refs_v3(child,false,NULL);
 payload:=jsonb_build_object('action','destination_with_refs','data',p_dados);SELECT * INTO op FROM folha_privado.operacoes WHERE empresa_id=u.empresa_id AND ator_id=u.id AND request_id=req;
 IF FOUND THEN IF op.payload IS DISTINCT FROM payload THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT';END IF;IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',op.token);END IF;IF p_versao IS DISTINCT FROM op.token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;RETURN op.resultado;END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id),'[]') INTO refs FROM public.folha_referencias r WHERE r.data=d AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END;
 SELECT coalesce(jsonb_agg(x),'[]') INTO xs FROM (SELECT x FROM public.folha_referencias r CROSS JOIN LATERAL jsonb_array_elements(r.intervals) x WHERE r.data=d AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END UNION ALL SELECT x FROM public.folha_registos r CROSS JOIN LATERAL jsonb_array_elements(r.intervals) x WHERE r.data=d AND r.obra_id IS DISTINCT FROM w AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END) q;
 xs:=xs||(p_dados->'intervals');IF jsonb_array_length(xs)>16 THEN RAISE EXCEPTION 'INTERVAL_LIMIT';END IF;PERFORM folha_privado.facts(xs,d);
 SELECT count(*) INTO cnt FROM (SELECT id FROM public.folha_referencias r WHERE r.data=d AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END UNION ALL SELECT id FROM public.folha_registos r WHERE r.data=d AND r.obra_id IS DISTINCT FROM w AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END) q;IF cnt>=4 THEN RAISE EXCEPTION 'DESTINATION_LIMIT';END IF;
 token:=encode(sha256(convert_to(jsonb_build_object('actor',u.id,'tenant',u.empresa_id,'payload',payload,'references',refs,'inner',preview->>'versao')::text,'UTF8')),'hex');
 IF NOT p_confirmar THEN RETURN preview||jsonb_build_object('versao',token);END IF;IF p_versao IS DISTINCT FROM token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;
 outcome:=folha_privado.destino_sem_refs_v3(child,true,preview->>'versao')||jsonb_build_object('request_id',req);INSERT INTO folha_privado.operacoes VALUES(u.empresa_id,u.id,req,payload,token,outcome,now());RETURN outcome;
END $destinationrefs$;
